import{c as e,Q as t,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Query","description":"","frontmatter":{},"headers":[{"level":1,"title":"Query","slug":"query"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Query.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Query.md"}'),s={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Kernel侧接口/Query.md"};function i(r,a,d,c,p,o){return t(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="query" tabindex="-1">Query <a class="header-anchor" href="#query" aria-label="Permalink to &quot;Query&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>查询handleId对应的通信任务已经完成的轮次，最多返回repeat轮。该接口默认在所有核上工作，用户也可以在调用前通过<a href="./../../../基础API/系统变量访问/GetBlockIdx.html">GetBlockIdx</a>指定其在某一个核上运行。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline int32_t Query(HcclHandle handleId)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>handleId</td><td>输入</td><td>对应通信任务的标识ID，只能使用Prepare原语接口的返回值。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;zh-cn_topic_0000001952464897_screen103142322514&quot;&gt;using HcclHandle = int8_t;&lt;/pre&gt;</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><ul><li>返回handleId对应的通信任务已执行的次数，最大值为repeat。</li><li>当执行异常时，返回-1。</li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>调用本接口前确保已调用过<a href="./InitV2.html">InitV2</a>和<a href="./SetCcTilingV2.html">SetCcTilingV2</a>接口。</li><li>入参handleId只能使用Prepare原语对应接口的返回值。</li><li>本接口在AIC核或者AIV核上调用必须与对应的Prepare接口的调用核保持一致。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGISTER_TILING_DEFAULT(ReduceScatterCustomTilingData); //ReduceScatterCustomTilingData为对应算子头文件定义的结构体</span></span>
<span class="line"><span>GET_TILING_DATA_WITH_STRUCT(ReduceScatterCustomTilingData, tilingData, tilingGM);</span></span>
<span class="line"><span>Hccl hccl;</span></span>
<span class="line"><span>GM_ADDR contextGM = AscendC::GetHcclContext&lt;0&gt;();  // AscendC自定义算子kernel中，通过此方式获取HCCL context</span></span>
<span class="line"><span>hccl.InitV2(contextGM, &amp;tilingData);</span></span>
<span class="line"><span>auto ret = hccl.SetCcTiling(offsetof(ReduceScatterCustomTilingData, mc2CcTiling));</span></span>
<span class="line"><span>if (ret != HCCL_SUCCESS) {</span></span>
<span class="line"><span>  return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>if (AscendC::g_coreType == AIC) {</span></span>
<span class="line"><span>    auto repeat = 10;</span></span>
<span class="line"><span>    HcclHandle handleId = hccl.ReduceScatter(sendBuf, recvBuf, 100, HcclDataType::HCCL_DATA_TYPE_INT8, HcclReduceOp::HCCL_REDUCE_SUM, repeat);</span></span>
<span class="line"><span>    hccl.Commit(handleId ); // 通知服务端可以执行上述的ReduceScatter任务</span></span>
<span class="line"><span>    int32_t finishedCount = hccl.Query(handleId);</span></span>
<span class="line"><span>    while (hccl.Query(handleId) &lt; repeat) {} // 等待查询到handleId对应的通信任务执行repeat次</span></span>
<span class="line"><span>    hccl.Finalize(); // 后续无其他通信任务，通知服务端执行上述ReduceScatter任务之后即可以退出</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,16)])])}const C=e(s,[["render",i]]);export{u as __pageData,C as default};
